import json, re, glob
_SERVICE_RE = re.compile(r"\b(http\s+server|https?\s+service|rest\s+api|web\s+server|web\s+service|http\s+service|api\s+server|api\s+endpoint|micro\s?service|flask|fastapi|uvicorn|gunicorn|http\.server|start\s+.{0,20}server|run\s+.{0,20}service|deploy\s+.{0,25}service|multi[- ]?protocol\s+service|verifier\s+will\s+(?:make|issue|send)\s+.{0,30}http|http\s+requests?\s+to\s+(?:test|check|verify|the))\b", re.IGNORECASE)
_LISTEN_RE = re.compile(r"\b(endpoint|listen(?:ing)?|bind|serve|port\s*\d{2,5}|:\d{3,5}\b|GET\s*/|POST\s*/|/query|/health|HTTP/1\.[01]|HTTP\s+200|HTTP\s+GET|HTTP\s+POST)\b", re.IGNORECASE)

def full_desc(t):
    d=json.load(open(t+'.messages.json'))
    msgs = d if isinstance(d,list) else d.get('messages',[])
    for m in msgs:
        c=m.get('content','')
        if isinstance(c,list): c=' '.join(str(x.get('text','')) for x in c if isinstance(x,dict))
        if m.get('role')=='user' and len(c)>100:
            return c
    return ''

armed_pass=[]; armed_fail=[]
for f in sorted(glob.glob('*.messages.json')):
    t=f[:-len('.messages.json')]
    try:
        r=json.load(open(t+'.result.json'))
    except: continue
    d=full_desc(t)
    if _SERVICE_RE.search(d) and _LISTEN_RE.search(d):
        (armed_pass if r['reward']==1 else armed_fail).append(t)
print("ARMED & PASSING (regression watch):")
for t in armed_pass: print("  ",t)
print("ARMED & FAILING:")
for t in armed_fail: print("  ",t)
EOF

